def decode_model_json_object(text: object) -> dict:
    """Accept one complete JSON object; never salvage a nested partial object."""
    source = str(text or "").strip().lstrip("\ufeff").strip()
    if not source:
        raise ValueError("empty_content")
    try:
        direct = json.loads(source)
    except json.JSONDecodeError:
        if source.startswith(("{", "[")):
            raise ValueError("incomplete_or_invalid_json") from None
    else:
        if not isinstance(direct, dict):
            raise ValueError("json_root_is_not_object")
        return direct
    fenced = re.findall(r"```(?:json)?\s*\n?(.*?)```", source, re.S | re.I)
    if fenced:
        if len(fenced) != 1:
            raise ValueError("ambiguous_json_blocks")
        source = fenced[0].strip()
    try:
        result = json.loads(source)
    except json.JSONDecodeError:
        start = source.find("{")
        if start < 0 or source.lstrip().startswith("["):
            raise ValueError("missing_json_object") from None
        try:
            result, end = json.JSONDecoder().raw_decode(source, start)
        except json.JSONDecodeError:
            raise ValueError("incomplete_or_invalid_json") from None
        if "{" in source[end:] or "```" in source[end:]:
            raise ValueError("ambiguous_json_objects")
    if not isinstance(result, dict):
        raise ValueError("json_root_is_not_object")
    return result

