def standard_model_json_object(text: object) -> dict:
    """Normalize complete model literals without completing truncated data."""
    source = str(text or "").strip().lstrip("\ufeff").strip()
    # Some gateways put a completed reasoning block in content rather than in
    # reasoning_content. Never interpret that block as the model's answer.
    source = re.sub(r"\A\s*<think(?:ing)?>.*?</think(?:ing)?>\s*", "", source, flags=re.S | re.I)
    if re.match(r"\A\s*<think(?:ing)?>", source, re.I):
        raise ValueError("unterminated_thinking_block")
    try:
        value = decode_model_json_object(source)
    except ValueError:
        literal = source
        fenced = re.fullmatch(r"```(?:json|python)?\s*\n?(.*?)```", literal, re.S | re.I)
        if fenced:
            literal = fenced[1].strip()
        if not (literal.startswith("{") and literal.endswith("}")):
            raise ValueError("incomplete_or_invalid_json") from None
        cleaned, quoted, escaped = [], False, False
        for index, char in enumerate(literal):
            if quoted:
                cleaned.append(char)
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    quoted = False
            else:
                if char == '"':
                    quoted = True
                if char == ",":
                    following = index + 1
                    while following < len(literal) and literal[following].isspace():
                        following += 1
                    if following < len(literal) and literal[following] in "}]":
                        continue
                cleaned.append(char)
        # literal_eval accepts common single-quoted/Python literals and trailing
        # commas, but never executes code or extracts a nested partial object.
        try:
            try:
                value = json.loads("".join(cleaned))
            except ValueError:
                value = ast.literal_eval(literal)
        except (ValueError, SyntaxError, TypeError, RecursionError):
            raise ValueError("incomplete_or_invalid_json") from None
        if not isinstance(value, dict):
            raise ValueError("json_root_is_not_object")
    def check(item):
        if isinstance(item, dict):
            if not all(isinstance(key, str) for key in item):
                raise ValueError("json_keys_must_be_strings")
            for child in item.values():
                check(child)
        elif isinstance(item, list):
            for child in item:
                check(child)
        elif item is not None and not isinstance(item, (str, int, float, bool)):
            raise ValueError("non_json_literal")
    check(value)
    # Reject NaN/Infinity and non-JSON types instead of silently converting them.
    return json.loads(json.dumps(value, ensure_ascii=False, allow_nan=False))

