def validate_semantic_json_repair(text: object, damaged: object = "", *, preserve_all_values: bool = False) -> dict:
    value = standard_model_json_object(text)
    if value.get("repair_status") == "unrecoverable":
        raise ValueError("semantic_json_unrecoverable")
    if not value:
        raise ValueError("empty_json_object")
    # A semantic converter cannot manufacture an answer from an empty response.
    if not str(damaged or "").strip():
        raise ValueError("semantic_json_missing_source")
    source = str(damaged)
    numbers = {float(match) for match in re.findall(r"(?<![\w])[-+]?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?", source)
               if len(match) < 100}
    def preserve(item, field=""):
        if isinstance(item, dict):
            for key, child in item.items():
                preserve(child, key)
        elif isinstance(item, list):
            for child in item:
                preserve(child, field)
        elif isinstance(item, (int, float)) and not isinstance(item, bool):
            if float(item) not in numbers:
                raise ValueError("semantic_json_invented_numeric_value")
        elif isinstance(item, str) and (preserve_all_values or field in {"content", "patch", "diff", "source"} or len(item) > 1000):
            escaped = json.dumps(item, ensure_ascii=False)[1:-1]
            if item not in source and escaped not in source:
                raise ValueError("semantic_json_changed_source_text")
    preserve(value)
    return value

